mapper.select:
SELECT 
FROM device_info_change_record
WHERE sn = #{sn}
ORDER BY create_time DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT 
FROM device_info_change_record
WHERE sn = #{sn}
  AND create_time >= #{from}
  AND create_time <= #{to}
ORDER BY create_time DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

mapper.delete:
DELETE FROM device_info_change_record
WHERE create_time < #{before}
LIMIT #{limit}
